{"content": "import sys


def solve(data):
    it = iter(data.split())
    n = int(next(it))
    k = int(next(it))
    steps = sorted({int(next(it)) for _ in range(k)})

    # win[pos] = True 表示轮到当前玩家时还剩 pos 颗且存在必胜策略
    # win[0] = False (轮到你时无石可取 => 对手取了最后一颗 => 你败)
    win = [False] * (n + 1)
    for pos in range(1, n + 1):
        for s in steps:
            if s > pos:
                break  # steps 已升序, 后续更大
            if not win[pos - s]:   # 走到一个让对手必败的局面
                win[pos] = True
                break

    if not win[n]:
        return "LOSE"
    # 数值最小的必胜首取数
    for s in steps:
        if s <= n and not win[n - s]:
            return "WIN %d" % s
    return "LOSE"


def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data) + "\n")


def selftest():
    # 期望值全部由独立朴素递归 (记忆化 minimax) 生成, 与本题解不共享逻辑
    from functools import lru_cache

    def brute(n, steps):
        s = tuple(steps)

        @lru_cache(maxsize=None)
        def w(pos):
            if pos == 0:
                return False
            return any(si <= pos and not w(pos - si) for si in s)

        if not w(n):
            return "LOSE"
        for si in s:
            if si <= n and not w(n - si):
                return "WIN %d" % si
        return "LOSE"

    cases = [(31, (1, 6, 10)), (19, (1,)), (1, (1,)), (2, (1,)),
             (4, (1, 3)), (5, (1, 4)), (6, (1, 4)), (7, (1, 4)), (80, (1, 2, 3))]
    ok = True
    for n, steps in cases:
        expect = brute(n, steps)
        inp = "%d %d\n%s\n" % (n, len(steps), " ".join(map(str, steps)))
        got = solve(inp)
        flag = "PASS" if got == expect else "FAIL"
        if got != expect:
            ok = False
        print("[%s] n=%d steps=%s got=%r expect=%r" % (flag, n, steps, got, expect))

    # 负向控制: 故意注入缺陷 (丢掉首步最小性, 直接取第一个可用必胜步的逆序)
    def broken(data):
        it = iter(data.split())
        n = int(next(it)); k = int(next(it))
        steps = sorted({int(next(it)) for _ in range(k)}, reverse=True)
        win = [False] * (n + 1)
        for pos in range(1, n + 1):
            for s in steps:
                if s <= pos and not win[pos - s]:
                    win[pos] = True
                    break
        if not win[n]:
            return "LOSE"
        for s in steps:
            if s <= n and not win[n - s]:
                return "WIN %d" % s
        return "LOSE"

    bad_inp = "31 3\n1 6 10\n"
    bad = broken(bad_inp)
    ctrl_ok = (bad != "WIN 6")
    print("[%s] negative-control broken()=%r (must differ from WIN 6)" %
          ("PASS" if ctrl_ok else "FAIL", bad))
    ok = ok and ctrl_ok

    print("SELFTEST", "PASS" if ok else "FAIL")
    return 0 if ok else 1


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--selftest":
        sys.exit(selftest())
    main()
